57	SipHash TextSearchQuery::getHash() const
58	{
59	    SipHash hash;
60	    hash.update(function_name);
61	    hash.update(search_mode);
62	    hash.update(direct_read_mode);
63	
64	    hash.update(tokens.size());
65	    for (const auto & token : tokens)
66	    {
67	        hash.update(token.size());
68	        hash.update(token);
69	    }
70	
71	    if (!patterns.empty())
72	    {
73	        hash.update(patterns.size());
74	        for (const auto & pattern : patterns)
75	        {
76	            if (const auto & re2 = pattern.getRE2())
77	            {
78	                hash.update(re2->pattern());
79	            }
80	            else
81	            {
82	                std::string required_substring;
83	                bool is_trivial;
84	                bool required_substring_is_prefix;
85	                pattern.getAnalyzeResult(required_substring, is_trivial, required_substring_is_prefix);
86	                hash.update(required_substring);
87	                hash.update(is_trivial);
88	                hash.update(required_substring_is_prefix);
89	            }
90	        }
91	    }
92	
93	    return hash;
94	}
