464	{
465	    const auto & condition_text = typeid_cast<const MergeTreeIndexConditionText &>(*state.condition);
466	    const auto & all_search_patterns = condition_text.getAllSearchPatterns();
467	
468	    if (all_search_patterns.empty())
469	    {
470	        can_use_like_dictionary_scan = true;
471	        return;
472	    }
473	
474	    auto sparse_index = loadSparseIndex(header_stream, state);
475	    if (sparse_index->empty())
476	    {
477	        can_use_like_dictionary_scan = true;
478	        return;
479	    }
