487	        /// TODO(ahmadov): Include the byte size of token infos into dictionary block to avoid multi-seek.
488	        UInt64 offset_in_file = sparse_index->getOffsetInFile(block_idx);
489	        dictionary_stream.seekToMark({offset_in_file, 0});
